<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><section class="info wrap"><h1>Your account</h1><p><?= esc($user['name']) ?><br><?= esc($user['email']) ?></p><?php if (session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?><?php if (session('success')): ?><p role="status"><?= esc(session('success')) ?></p><?php endif ?><h2>Change password</h2><form class="account-form" method="post" action="<?= site_url('account/password') ?>"><?= csrf_field() ?><label for="current_password">Current password</label><input id="current_password" type="password" name="current_password" autocomplete="current-password" required><label for="password">New password</label><input id="password" type="password" name="password" minlength="8" maxlength="72" autocomplete="new-password" required><label for="password_confirm">Confirm new password</label><input id="password_confirm" type="password" name="password_confirm" minlength="8" maxlength="72" autocomplete="new-password" required><button class="button button-dark" type="submit">Update password</button></form></section><?= $this->endSection() ?>
